def gpx_fields_to_xml(instance: Any, tag: str, version: str,
    custom_attributes: Dict[str, str]={}, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='', empty_body: bool=False) ->str:
    if instance is None:
        return ''
    if not prettyprint:
        indent = ''
    fields = instance.gpx_10_fields
    if version == '1.1':
        fields = instance.gpx_11_fields
    tag_open = f'\n{indent}<{tag}'
    body = []
    attributes = []
    if custom_attributes:
        for attr_name, attr_value in custom_attributes.items():
            attributes.append(f' {attr_name}="{mod_utils.make_str(attr_value)}"')
    node_path = []
    current_tag = tag
    for gpx_field in fields:
        if isinstance(gpx_field, str):
            gpx_field_str = gpx_field.partition(':')[0]
            if gpx_field_str.startswith('/'):
                if node_path:
                    closed = node_path.pop()
                    body.append(f'\n{indent}</{closed}>')
            else:
                node_path.append(gpx_field_str)
                body.append(f'\n{indent}  <{gpx_field_str}>')
        else:
            value = getattr(instance, gpx_field.name)
            if gpx_field.attribute:
                if value is not None:
                    xml_value = gpx_field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=indent)
                    if xml_value:
                        attributes.append(f' {xml_value}')
            else:
                xml_value = gpx_field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=f'{indent}  ')
                if xml_value:
                    body.append(xml_value)
    if not body and not empty_body:
        return ''
    result = [tag_open]
    result.extend(attributes)
    result.append('>')
    result.extend(body)
    result.append(f'\n{indent}</{tag}>')
    return ''.join(result)
